## Validating the Auth Module Before Payment Processing

Good security practice here. Based on your dependency graph, here's a structured approach:

### 1. Explicit Interface Verification at Startup

```python
# app/payments/dependencies.py
import importlib
import inspect
from typing import Callable

REQUIRED_AUTH_EXPORTS = {
    "get_api_key": {"callable": True, "min_params": 1},
    "validate_token": {"callable": True, "min_params": 1},
    "AuthService": {"callable": True},
}

def verify_auth_module() -> None:
    """
    Verify auth module exports expected interface before
    payment module initializes. Fail fast if anything is wrong.
    """
    try:
        auth_module = importlib.import_module("app.auth")
    except ImportError as e:
        raise RuntimeError(f"Auth module unavailable: {e}") from e

    for name, requirements in REQUIRED_AUTH_EXPORTS.items():
        obj = getattr(auth_module, name, None)

        if obj is None:
            raise RuntimeError(f"Auth module missing required export: {name}")

        if requirements.get("callable") and not callable(obj):
            raise RuntimeError(f"Auth export '{name}' is not callable")

        if "min_params" in requirements:
            sig = inspect.signature(obj)
            param_count = len(sig.parameters)
            if param_count < requirements["min_params"]:
                raise RuntimeError(
                    f"Auth export '{name}' has too few parameters: "
                    f"expected >= {requirements['min_params']}, got {param_count}"
                )
```

### 2. Token Validation Before Any Payment Call

```python
# app/payments/processor.py
from dataclasses import dataclass
from app.auth import validate_token, get_api_key
from app.payments.dependencies import verify_auth_module

@dataclass
class ValidationResult:
    valid: bool
    reason: str = ""

def validate_auth_before_payment(token: str, required_scope: str) -> ValidationResult:
    """
    Explicit auth check that must pass before any payment
    processing begins. Never assume auth is statefully valid.
    """
    if not token or not token.strip():
        return ValidationResult(False, "Empty token rejected")

    try:
        result = validate_token(token)
    except Exception as e:
        # Don't let auth exceptions silently pass
        return ValidationResult(False, f"Token validation raised: {type(e).__name__}")

    if not result.is_valid:
        return ValidationResult(False, "Token invalid or expired")

    if required_scope not in result.scopes:
        return ValidationResult(False, f"Missing required scope: {required_scope}")

    return ValidationResult(True)


class PaymentProcessor:
    def __init__(self):
        # Fail fast: verify auth interface exists before accepting any requests
        verify_auth_module()

    def process_payment(self, token: str, amount: float, ...) -> dict:
        auth_check = validate_auth_before_payment(token, required_scope="payments:write")

        if not auth_check.valid:
            raise PermissionError(f"Auth validation failed: {auth_check.reason}")

        # Only reach payment logic if auth explicitly passed
        return self._execute_payment(amount, ...)
```

### 3. Integration Test That Mirrors Production Validation

```python
# tests/test_auth_payment_integration.py
import pytest
from app.payments.dependencies import verify_auth_module
from app.payments.processor import PaymentProcessor, validate_auth_before_payment

class TestAuthModuleContract:
    """
    These tests verify the auth module satisfies the contract
    that payments depends on. Run these before deploying.
    """

    def test_auth_module_exports_are_present(self):
        # Should not raise
        verify_auth_module()

    def test_empty_token_is_rejected(self):
        result = validate_auth_before_payment("", required_scope="payments:write")
        assert not result.valid

    def test_invalid_token_is_rejected(self, mock_auth_invalid):
        result = validate_auth_before_payment("bad-token", required_scope="payments:write")
        assert not result.valid

    def test_missing_scope_is_rejected(self, mock_auth_valid_no_scope):
        result = validate_auth_before_payment("good-token", required_scope="payments:write")
        assert not result.valid

    def test_payment_processor_fails_if_auth_missing(self, monkeypatch):
        monkeypatch.delattr("app.auth", "get_api_key")
        with pytest.raises(RuntimeError, match="missing required export"):
            PaymentProcessor()
```

### Key Principles Applied

| Practice | Why It Matters Here |
|---|---|
| **Fail fast at startup** | Don't discover broken auth during a live payment |
| **Explicit scope checks** | `get_api_key` presence doesn't mean payment permission |
| **No silent exception swallowing** | Auth errors must surface, not default to "allow" |
| **Contract tests separate from unit tests** | Verifies the actual integration, not mocks of mocks |
| **Never assume stateful validity** | Re-validate on each payment call, not just at login |

The most important rule: **a failed auth check must always result in rejection, never a fallback that permits the operation**. Make sure your error handling paths don't accidentally create a bypass.
